INSERT INTO public.section_settings (section_key, label, eyebrow_translations, title_translations, highlight_translations, description_translations, is_visible, display_order)
VALUES
  ('testimonials', 'Testimonials', '{"en":"Testimonials","de":"Kundenstimmen","fr":"Témoignages","es":"Testimonios"}'::jsonb, '{"en":"What Our Clients","de":"Das sagen unsere Kunden","fr":"Ce que disent nos clients","es":"Lo que dicen nuestros clientes"}'::jsonb, '{"en":"Say","de":"","fr":"","es":""}'::jsonb, '{"en":"Don''t take our word for it — hear from the brands we''ve helped scale.","de":"Erfahren Sie direkt von unseren Kunden, wie sie die Zusammenarbeit mit STRATIFIT erlebt haben.","fr":"Découvrez directement l''expérience des clients qui ont travaillé avec STRATIFIT.","es":"Conozca directamente la experiencia de los clientes que han trabajado con STRATIFIT."}'::jsonb, true, 60)
